create or replace function private.aios_audit_append() returns trigger language plpgsql security definer set search_path='' as $$ declare v_prev text; v_last_created timestamptz; v_payload text; begin perform pg_advisory_xact_lock(hashtextextended(coalesce(new.organization_id::text,''),0)); select event_hash,created_at into v_prev,v_last_created from public.aios_audit_events where organization_id=new.organization_id order by created_at desc,id desc limit 1; if v_last_created is not null and new.created_at<=v_last_created then new.created_at=v_last_created+interval '1 microsecond'; end if; new.previous_event_hash=coalesce(v_prev,'GENESIS:'||new.organization_id::text); v_payload=jsonb_build_object('id',new.id,'organization_id',new.organization_id,'actor_user_id',new.actor_user_id,'actor_type',new.actor_type,'agent_id',new.agent_id,'mission_id',new.mission_id,'task_id',new.task_id,'invocation_id',new.invocation_id,'event_type',new.event_type,'previous_state',new.previous_state,'new_state',new.new_state,'tool_name',new.tool_name,'risk_level',new.risk_level,'arguments_hash',new.arguments_hash,'result_hash',new.result_hash,'approval_id',new.approval_id,'created_at',new.created_at,'metadata',new.metadata,'previous_event_hash',new.previous_event_hash)::text||new.previous_event_hash; new.event_hash=encode(extensions.digest(v_payload,'sha256'),'hex'); return new; end; $$;
